import{_ as c,l as d,o as a,c as l,v as o,p as n,x as r,d as i,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"SGLang Router","description":"","frontmatter":{"title":"SGLang Router","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sglang-router.md","filePath":"llm/sglang-router.md","lastUpdated":1789023840000}'),h={name:"llm/sglang-router.md"};function g(u,e,w,_,P,m){const t=d("Mermaid");return a(),l("div",null,[e[1]||(e[1]=o('<h1 id="sglang-router" tabindex="-1">SGLang Router <a class="header-anchor" href="#sglang-router" aria-label="Permalink to &quot;SGLang Router&quot;">​</a></h1><div class="epigraph"><p>引擎内的 radix 树只能看见本进程的页；集群入口要用另一棵前缀树决定请求去哪台 worker，否则多副本把命中率摊成近似均匀随机。</p><footer>—— SGLang Model Gateway / sglang-router 文档；树算法对照 Zheng et al., NeurIPS 2024</footer></div><p><a href="/llm/sglang">SGLang</a> 的 RadixAttention 解决单运行时里「请求结束后 KV 先留着、按最长前缀匹配」。复制出 \\(N\\) 个 SRT 进程之后，若不在入口做同样的事，第 \\(i\\) 条共享系统提示的请求会以 \\(1/N\\) 的概率打到持有该前缀的那台，命中期望按副本数稀释。<code>sglang-router</code>（Rust 实现，Python 入口 <code>sglang_router.launch_router</code>，近期文档也称 SGLang Model Gateway）是这层入口：负载策略、PD 分离时的双池选择、健康检查与重试。本篇写路由器，不写树节点如何裂边——那是 <a href="/llm/sglang-radix-tree">前缀树</a> 的职责。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>数据并行多副本是多份权重、多份 KV、多棵 radix。引擎没有全局页表。轮询或随机对无共享负载是公平的；对多轮聊天、few-shot、智能体循环则系统性地破坏缓存局部性。Power-of-two 选择（随机抽两台、挑更闲的）能抑制羊群，但看不见前缀。需要一种策略：既维护「哪台 worker 上有过哪些前缀」的近似视图，又在某台过热时把流量溢出去。</p><p>PD 分离把问题再乘一次。前填 worker 与解码 worker 是两份名单；前填侧要缓存感知，解码侧往往要负载感知并遵守 <a href="/llm/decode-affinity">亲和</a>——KV 已经交给某台解码机之后，后续 token 不能再按前缀随便换家。路由器还要合并前填元数据与解码输出、处理 bootstrap 端口、在 Kubernetes 里用 selector 发现两类 Pod。这些都不该塞回单个 SRT 进程。</p><h3 id="入口树不是引擎树的副本" tabindex="-1">入口树不是引擎树的副本 <a class="header-anchor" href="#入口树不是引擎树的副本" aria-label="Permalink to &quot;入口树不是引擎树的副本&quot;">​</a></h3><p>引擎 radix 指向 GPU 页，带引用计数与 LRU，和运行中 batch 抢同一池。路由器的树只存前缀 token 与 worker 身份，为的是选机器，不存 KV 张量。两棵树会暂时不一致：worker 已淘汰某前缀，路由器仍以为命中，请求打过去后引擎会全额前填——这是缓存感知路由的固有陈旧，要用淘汰周期、树大小上限和 worker 回报来逼近，而不能假设强一致。</p><p><span class="marginnote"><code>--policy cache_aware</code> 默认维护的是路由器进程里的树。它不会通过 RDMA 去读 worker 的页表。把「开了 cache_aware」理解成「集群级 Mooncake」，层位错了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>文档列出的策略包括：<code>random</code>、<code>round_robin</code>、<code>power_of_two</code>（抽两台比负载）、<code>cache_aware</code>（默认：前缀局部性加负载阈值）、<code>bucket</code>（按负载分桶）。<code>cache_aware</code> 可调 <code>--cache-threshold</code>、<code>--balance-abs-threshold</code>、<code>--balance-rel-threshold</code>、<code>--eviction-interval</code>、<code>--max-tree-size</code>：重叠不够高或某 worker 明显更忙时，退回均衡，以免热前缀把一台打满。Load Monitor 给 power-of-two 与 cache-aware 提供实时负载；后台健康检查、带抖动的重试、worker 级熔断和令牌桶限流构成可靠性内核。</p><p>PD 模式：<code>--pd-disaggregation</code>，<code>--prefill</code> / <code>--decode</code> 列出两类 URL，前填项可带 bootstrap 端口。<code>--prefill-policy</code> 与 <code>--decode-policy</code> 可分别设，例如前填 <code>cache_aware</code>、解码 <code>power_of_two</code>。路由器负责把前填结果注入解码请求并流式回客户端。Kubernetes 上用 <code>--service-discovery</code> 加 <code>--prefill-selector</code> / <code>--decode-selector</code> 动态发现；历史上出现过「动态发现 + PD + cache_aware 时树未初始化、选不出 worker」的缺陷，后续用 <code>init_pd_cache_aware_policies</code> 在注册时把两类 worker 填进全局策略（见 sgl-project/sglang#23573 一类修复）。运维要确认当前发行版在 PD 下确实给树喂了 worker，而不是只看命令行写了 <code>cache_aware</code>。</p><p>多模型网关（IGW）允许按模型覆盖策略。gRPC、MCP 集成出现在较新的 gateway 文档里，属于入口扩展，不是 RadixAttention 论文的范围。</p>',13)),(a(),n(p,null,{default:r(()=>[s(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%22%5D%20--%3E%20R%5B%22sglang-router%22%5D%0A%20%20R%20--%3E%20CA%5B%22cache_aware%20%E5%89%8D%E7%BC%80%E6%A0%91%22%5D%0A%20%20R%20--%3E%20LM%5B%22Load%20Monitor%22%5D%0A%20%20CA%20--%3E%20P%5B%22Prefill%20workers%22%5D%0A%20%20LM%20--%3E%20D%5B%22Decode%20workers%22%5D%0A%20%20P%20--%3E%7C%22KV%20%E5%85%83%E6%95%B0%E6%8D%AE%20%2F%20bootstrap%22%7C%20D%0A%20%20D%20--%3E%20C%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h3 id="与引擎调度的两级优化" tabindex="-1">与引擎调度的两级优化 <a class="header-anchor" href="#与引擎调度的两级优化" aria-label="Permalink to &quot;与引擎调度的两级优化&quot;">​</a></h3><p>引擎内缓存感知调度按最长匹配前缀排序等待队列，Zheng 等人给出离线 DFS 最优命中的定理（NeurIPS 2024 / arXiv:2312.07104）。路由器决定的是<strong>哪台机器上的树</strong>会被这道请求加厚。两级都做最长前缀，命中才接近单机论文数字；只做引擎、入口轮询，论文里的 6.4× 量级不会在多副本上复现。只做入口、引擎关闭 radix，入口树指向的工人仍然每条请求冷启动。正确叠法是：入口 cache-aware + 引擎 RadixAttention + 可选的 <a href="/llm/mooncake-store">Mooncake Store</a> 跨机对象。</p><p>DP 感知调度（文档中的 DP-aware）处理单进程内多数据并行 rank 的选择，与跨进程 worker 选择不是同一层。配置时不要把 <code>--dp-size</code> 与路由器副本数混成一个旋钮。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>cache-aware 的机制是<strong>用 CPU 上的前缀索引逼近 GPU 上的页布局</strong>。插入发生在请求被送到某 worker 之后（或并行地根据提示预插入）；淘汰按时间间隔与树大小，防止路由器内存无限涨。阈值让算法在「跟缓存走」和「跟负载走」之间切换：相对空闲差超过 <code>balance-rel-threshold</code> 时，宁可牺牲一点命中，也避免一台的 TBT 先爆。这与 Dynamo Smart Router 的 overlap score、Ray Serve 的前缀路由是同一权衡。</p><p>PD 下前填命中省的是 TTFT；解码侧 power-of-two 保的是 TBT 与 KV 容量。bootstrap 端口让解码工人找到前填侧的传输端点，语义上等于 DistServe 的 pull 握手，实现可以是 NIXL、Mooncake Transfer Engine 或引擎自带 connector。路由器自己通常不搬 GB 级 KV，只搬元数据；把传输做进路由器进程会把它变成带宽瓶颈。</p><p><span class="marginnote">熔断是 worker 级的。一台前填机连续失败应从树里摘掉，否则 cache-aware 会因为「它还有热前缀」而持续把流量送进坏节点。健康检查失败必须同时更新策略里的 worker 集。</span></p><h3 id="陈旧命中与颠簸" tabindex="-1">陈旧命中与颠簸 <a class="header-anchor" href="#陈旧命中与颠簸" aria-label="Permalink to &quot;陈旧命中与颠簸&quot;">​</a></h3><p>路由器树比引擎树更大、更旧时，会出现「假命中」：请求被送到以为有前缀的机器，引擎 LRU 早已释放。假命中的代价是一次普通前填加上错误的亲和，通常仍可接受。更坏的是颠簸：两台来回抢同一热前缀，谁都形不成稳定的厚分支。阈值与 eviction 间隔是抑制颠簸的旋钮；把 <code>max-tree-size</code> 设太小，树频繁清空，策略退化成随机。观测应打「路由以为的匹配长度」和「引擎回报的真实匹配长度」，两者长期分叉就是陈旧或 bug。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>路由器是新的故障域。Rust 二进制崩溃则全集群入口不可用，需要多实例入口再在前面做无状态四层均衡——但无状态层不能再做轮询把 cache-aware 打散，要用一致性哈希把同一用户粘到同一路由器实例，否则每台路由器一棵互不相干的树。这是缓存感知入口的经典递归：入口本身也要亲和。</p><p>K8s 动态发现下，worker 注册与策略初始化的时序 bug 会表现为间歇性「Failed to select prefill/decode worker」。升级发行版、确认 <code>init_pd_cache_aware_policies</code> 被调用，比把策略改回 <code>round_robin</code> 再忘记改回来更正确。gRPC / HTTP 双协议、MCP 工具调用不要默认假定与 OpenAI 路径走同一套 cache 键——工具结果若进入提示，键必须包含那一段，否则多步智能体会在路由器上看不见共享。</p><p>不要把 sglang-router 写成论文贡献。NeurIPS 文本写的是单运行时 radix 与前端共设计；路由器是工程仓库为多副本与 PD 补的控制面，引用应以仓库文档与 PyPI <code>sglang-router</code> 说明为准，命中率数字仍以论文实验节的单机设定为上界。</p><p><span class="marginnote">出处钉 <a href="https://github.com/sgl-project/sglang" target="_blank" rel="noreferrer">https://github.com/sgl-project/sglang</a> 中 Model Gateway / router 文档、PyPI <code>sglang-router</code>，以及 Zheng et al., <em>SGLang: Efficient Execution of Structured Language Model Programs</em>, NeurIPS 2024（arXiv:2312.07104）对引擎内树与缓存感知调度的定义。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SGLang Router 在集群入口做 worker 选择；cache-aware 维护前缀→机器的索引，不保存 KV。</li><li>PD 模式下前填与解码分策略、分发现；路由器合并元数据，传输仍走工人之间的数据面。</li><li>与引擎 RadixAttention 是两级：入口选树，引擎用树。只开一层，多副本收益到不了论文数字。</li><li>负载阈值防止热前缀羊群；健康检查必须把坏节点从树里摘掉。</li><li>多路由器实例时，入口本身也需要亲和，否则每棵树各记各的。</li><li>出处：sglang-router / Model Gateway 文档；引擎侧树见 Zheng et al., NeurIPS 2024。</li></ul>',16))])}const b=c(h,[["render",g]]);export{k as __pageData,b as default};
